struct PartyRoleQuanlifier {
    void setClientRole(ClientRole v) {
        auto rv = v.raw_value();
        bits &= clear_mask<int8_t, 0, 2>;
        bits |= rv;
    }

    ClientRole getClientRole() {
        auto v = bits&get_mask<int8_t, 0, 2>;
        return int8_t(v);
    }

    void setIDMRole(IDMRole v) {
        auto rv = v.raw_value();
        rv <<= 2;
        bits &= clear_mask<int8_t, 2, 2>;
        bits |= rv;
    }

    IDMRole getIDMRole() {
        auto v = bits&get_mask<int8_t, 2, 2>;
        v >>= 2;
        return int8_t(v);
    }

    void setEDMRole(EDMRole v) {
        auto rv = v.raw_value();
        rv <<= 4;
        bits &= clear_mask<int8_t, 4, 2>;
        bits |= rv;
    }

    EDMRole getEDMRole() {
        auto v = bits&get_mask<int8_t, 4, 2>;
        v >>= 4;
        return int8_t(v);
    }

    void clear() {
        bits = 0;
    }
    int8_t bits;
 };

template<typename ostreamT>
ostreamT& operator<<(ostreamT& os, const PartyRoleQuanlifier& v) {
    os << "ClientRole=" << v.getClientRole();
    os << "|IDMRole=" << v.getIDMRole();
    os << "|EDMRole=" << v.getEDMRole();
}
