    Capacity capacity{Capacity::null};
    AlgoIndicator algoIndicator{AlgoIndicator::null};
    u16 appendageLength;
    //this member should be only varlen member and the last one
    auto appendage() {
        return OptionalByLengthRef<OrderAckAppendageEntry, AppendixKeyEnum>(begin()+size(), appendageLength);
    
    char* begin() {return reinterpret_cast<char*>(this);}
    const char* cbegin() const {return reinterpret_cast<char*>(this);}
    char* end() {return begin()+length();}
    const char* cend() const {return begin()+length();}
    size_t size() const {return sizeof(OrderAck);}
    size_t var_size() const {return appendage().end()-begin();}
};
#pragma pack()
inline std::ostream& operator<<(std::ostream& os, const OrderAck& msg) {
    os << static_cast<const Header&>(msg);
    os << "msgType=" << msg.msgType << ";"
       << "timestamp=" << msg.timestamp << ";"
       << "userRefNum=" << msg.userRefNum << ";"
       << "price=" << msg.price << ";"
       << "orderRefNum=" << msg.orderRefNum << ";"
       << "side=" << msg.side << ";"
       << "orderBook=" << msg.orderBook << ";"
       << "qty=" << msg.qty << ";"
       << "user=" << msg.user << ";"
       << "EDM=" << msg.EDM << ";"
       << "IDM=" << msg.IDM << ";"
       << "clientID=" << msg.clientID << ";"
       << "partyRoleQuanlifier=" << msg.partyRoleQuanlifier << ";"
       << "capacity=" << msg.capacity << ";"
       << "algoIndicator=" << msg.algoIndicator << ";"
       << "appendageLength=" << msg.appendageLength << ";"
       << "appendage=" << const_cast<OrderAck&>(msg).appendage() << ";"
       << "}";
    return os;
}















